# Lenyűgöző, Modern 3D/WebGL Webapp – Teljes Kódfrissítés

## Főbb Jellemzők

- **3D/WebGL interaktív felület** (Three.js)
- **Gyors, reszponzív, mobilbarát** dizájn (Tailwind CSS)
- **Modern, letisztult UI** (React + Vite)
- **Valós idejű AI chat** (Cerebras, OpenAI, Gemini, Exa integráció)
- **Biztonságos, környezeti változó alapú kulcskezelés**
- **PostgreSQL adatbázis támogatás**
- **Sötét/világos mód, animációk, parallax effektek**
- **Könnyen bővíthető, moduláris architektúra**

## 1. Frontend: React + Three.js + Tailwind

### `src/App.jsx`

```jsx
import React, { useRef, useEffect } from "react";
import { Canvas } from "@react-three/fiber";
import { OrbitControls, Stars } from "@react-three/drei";
import ChatPanel from "./components/ChatPanel";
import "./App.css";

function RotatingCube() {
  const mesh = useRef();
  useEffect(() => {
    let frame;
    const animate = () => {
      if (mesh.current) {
        mesh.current.rotation.x += 0.01;
        mesh.current.rotation.y += 0.01;
      }
      frame = requestAnimationFrame(animate);
    };
    animate();
    return () => cancelAnimationFrame(frame);
  }, []);
  return (
    <mesh ref={mesh} scale={1.5}>
      <boxGeometry args={[2, 2, 2]} />
      <meshStandardMaterial color="#00bfff" metalness={0.7} roughness={0.2} />
    </mesh>
  );
}

export default function App() {
  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-blue-900 flex flex-col">
      <header className="p-6 text-center text-4xl font-bold text-white drop-shadow-lg">
        Lenyűgöző 3D AI Webapp 🚀
      </header>
      <main className="flex-1 flex flex-col md:flex-row">
        <section className="w-full md:w-2/3 h-[500px]">
          <Canvas camera={{ position: [0, 0, 7] }}>
            <ambientLight intensity={0.5} />
            <pointLight position={[10, 10, 10]} />
            <Stars radius={100} depth={50} count={5000} factor={4} />
            <RotatingCube />
            <OrbitControls />
          </Canvas>
        </section>
        <section className="w-full md:w-1/3 p-4">
          <ChatPanel />
        </section>
      </main>
      <footer className="p-4 text-center text-gray-300">
        &copy; 2025 Lenyűgöző AI Webapp. Minden jog fenntartva.
      </footer>
    </div>
  );
}
```

### `src/components/ChatPanel.jsx`

```jsx
import React, { useState } from "react";

export default function ChatPanel() {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);

  const sendMessage = async () => {
    if (!input.trim()) return;
    setLoading(true);
    setMessages([...messages, { role: "user", content: input }]);
    try {
      const res = await fetch("/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: input }),
      });
      const data = await res.json();
      setMessages((msgs) => [...msgs, { role: "assistant", content: data.chunk }]);
    } catch (e) {
      setMessages((msgs) => [...msgs, { role: "assistant", content: "Hiba történt!" }]);
    }
    setInput("");
    setLoading(false);
  };

  return (
    <div className="bg-white/10 rounded-xl shadow-lg p-4 h-full flex flex-col">
      <div className="flex-1 overflow-y-auto space-y-2 mb-2">
        {messages.map((msg, i) => (
          <div key={i} className={`p-2 rounded ${msg.role === "user" ? "bg-blue-200 text-right" : "bg-gray-200 text-left"}`}>
            {msg.content}
          </div>
        ))}
      </div>
      <div className="flex gap-2">
        <input
          className="flex-1 p-2 rounded border"
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyDown={e => e.key === "Enter" && sendMessage()}
          placeholder="Írj ide..."
          disabled={loading}
        />
        <button
          className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
          onClick={sendMessage}
          disabled={loading}
        >
          Küldés
        </button>
      </div>
    </div>
  );
}
```

